def verify_isbn(isbn: str) -> str:
    assert len(isbn) == 10, "ISBN number must be 10 digits long."
    digits = [int(d) if d.isdigit() else 10 if d == 'X' else 0 for d in isbn[:-1]]
    weight = [1, 3, 5, 7, 9, 1, 3, 5, 7, 9]
    checksum = sum(d * w for d, w in zip(digits, weight)) % 11
    if checksum == 10:
        checksum = 'X'
    return isbn if checksum == int(isbn[-1]) else isbn[:-1] + str(checksum)

def verify_isbn(isbn: str) -> str:
    def calculate_isbn_checksum isbn: str:
        def char_to_digit(char: str) -> int:
            if char.isdigit():
                return int(char)
            elif char.upper() in 'X':
                return 10
            raise ValueError(f"Invalid character in ISBN: {char}")

        sum = 0
        for i, char in enumerate(isbn[:-1]):
            sum += char_to_digit(char) * (10 - i)
        digit = 11 - sum % 11
        if digit == 10:
            digit = 'X'
        return str(digit)

    if len(isbn) != 13 or not isbn[0].isdigit() or not isbn[1].isdigit() or (isbn[2] != '-' and isbn[2] != 'x'):
        return "Invalid ISBN number format."

    expected_checksum = isbn[12]
    computed_checksum = calculate_isbn_checksum(isbn[0:-1])

    if computed_checksum == expected_checksum:
        return "Right"
    else:
        corrected_isbn = isbn[:-1] + computed_checksum
        return corrected_isbn

