def count_passing_ways(n, m):
    mod = 10**9 + 7
    dp = [[0] * m for _ in range(n)]
    for i in range(n):
        dp[i][0] = i

    for i in range(1, n):
        dp[i][0] = (2 * dp[(i - 1) % n][0]) % mod

    for i in range(1, n):
        for j in range(1, m):
            dp[i][j] = (2 * dp[(i - 1) % n][j - 1] + dp[(i + 1) % n][j - 1]) % mod

    return dp[n - 1][m - 1]

def count_passing_ways(n: int, m: int) -> int:
    if n == 1:
        return 1

    # Create a table to store the number of ways for each state and operation
    transition_table = [[0] * (m + 1) for _ in range(n)]

    # Base case: When ball is in position 0, there is only one way (pass to the right)
    transition_table[0][1] = 1

    # Fill the transition table using dynamic programming
    for i in range(1, n):
        for j in range(1, m + 1):
            if j % 2 == 0:
                transition_table[i][j] = transition_table[(i + 1) % n][j // 2]
            else:
                transition_table[i][j] = transition_table[(i - 1) % n][j // 2] + transition_table[(i + 1) % n][(j // 2 + 1) % m]

    # The number of ways to start in position 0 after m passes is the value in the bottom right corner
    return transition_table[0][m]

