def max_happiness(n: int, m: int, items: List[Tuple[int, int]]) -> int:
    # Initialize a table to store the maximum importance values for each price
    dp = [[0] * (m + 1) for _ in range(n + 1)]

    # Fill the DP table
    for price in range(1, n + 1):
        for item in range(1, m + 1):
            i = item - 1
            dp[price][item] = dp[price][item - 1]
            if price >= items[i][0]:
                dp[price][item] = max(dp[price][item], dp[price - items[i][0]][item - 1] + items[i][1])

    # The maximum importance value for the budget n is the last element of the dp table
    return dp[n][m]

