def largest_prime_factor(n: int) -> int:

    # Handle cases where n is 2 or less
    if n <= 2:
        return n

    # Initialize the largest prime factor
    largest_prime = -1

    # Check for factors from 2 to the square root of 'n'
    for i in range(2, int(math.sqrt(n)) + 1):
        if n % i == 0:
            largest_prime = i  # Set this as the larger prime factor

    # If the loop completes without finding a factor, 'n' itself is the largest prime factor
    return largest_prime

def largest_prime_factor(n: int) -> int:
