    from math import comb
    return comb(n+x-1, x-1)

def count_partitions(n: int, k: int, x: int) -> int:
    dp = [[0] * (k + 1) for _ in range(n + 1)]

    # Base case: There's exactly one way to partition 0 into k parts (the empty set)
    for i in range(k + 1):
        dp[0][i] = 1

    # Fill the dp table
    for i in range(1, n + 1):
        for j in range(1, min(k, i) + 1):
            lower_bound = max(x, i - j)
            dp[i][j] = dp[i - lower_bound][j - 1] + dp[i - 1][j]

    return dp[n][k]

def count_sequences(n: int, last: int, memo: Dict[int, int]) -> int:
    if (n, last) in memo:
        return memo[(n, last)]
    if n == 0 and last == 0:
        return 1
    if n == 0:
        return 0
    memo[(n, last)] = 0
    if last > 0:
        memo[(n, last)] += count_sequences(n, last - n, memo)
        memo[(n, last)] += count_sequences(n, last // 2, memo)

    return memo[(n, last)]

def count_sequences(n: int, last: int, memo: dict) -> int:
    if last == n:
        return 1
    if last > n or last not in memo:
        memo[last] = count_sequences(n, last + 1, memo) + count_sequences(n, 1, memo)
    return memo[last]

def count_sequences(n: int, last: int, memo: dict) -> int:
    if n == 1:
