    if last == 6:
        return 42 if n == 1 else 16
    if memo.get(last):
        return memo[last]
    memo[last] = count_sequences(n, last//2, memo) + count_sequences(n, last//3, memo) + count_sequences(n, last//4, memo)
    return memo[last]

