def preorder_traversal(inorder: str, postorder: str) -> str:
    if not inorder or not postorder:
        return ''

    root = postorder[-1]
    root_index = inorder.index(root)

    left_inorder = inorder[:root_index]
    right_inorder = inorder[root_index + 1:]
    left_postorder = postorder[:root_index]
    right_postorder = postorder[root_index:-1]

    return root + preorder_traversal(left_inorder, left_postorder) + preorder_traversal(right_inorder, right_postorder)

def preorder_traversal(inorder: str, postorder: str) -> str:
    if not postorder:
        return ""
    root = postorder[-1]
    left_subtree inorder = inorder[:inorder.index(root)]
    left_subtree postorder = postorder[:inorder.index(root)]
    right_subtree inorder = inorder[inorder.index(root) + 1:]
    right_subtree postorder = postorder[inorder.index(root) + 1:-1]

    return root + preorder_traversal(left_subtree inorder, left_subtree postorder) + preorder_traversal(right_subtree inorder, right_subtree postorder)

def preorder_traversal(inorder: str, postorder: str) -> str:
    in_map = {char: i for i, char in enumerate(inorder)}
    stack = deque()
    result = []

    for char in postorder:
        while stack and stack[-1] == inorder[in_map[char] - 1]:
            val = stack.pop()
            result.append(val)
        stack.append(char)

    while stack:
        result.append(stack.pop())

    return ''.join(result)

