        for old, new in rules:
            s = s.replace(old, new)
        return s

    def bfs(start: str, end: str) -> Union[int, str]:
        if start == end:
            return 0
        queue = collections.deque([(start, 0)])
        visited = set([start])
        step = 0
        while queue:
            size = len(queue)
            for _ in range(size):
                if queue[0][0] == end:
                    return queue[0][1]
                for new in rules:
                    new_string = transform_string(queue[0][0], new)
                    if new_string not in visited:
                        visited.add(new_string)
                        queue.append((new_string, queue[0][1] + 1))
            step += 1
        return "NO ANSWER!"

