    return total_trees

def remaining_trees_after_clearing(l: int, areas: List[Tuple[int, int]]) -> int:
    count = l
    for start, end in areas:
        if start <= end <= count:
            count -= end + 1 - start
    return count

def max_herb_value(T: int, M: int, herbs: List[Tuple[int, int]]) -> int:
    # Create a 2D table to store the maximum value for each subproblem
    dp = np.zeros((M+1, T+1))

    # Fill the table using dynamic programming
    for i in range(1, M+1):
        for j in range(1, T+1):
            herb_time, herb_value = herbs[i-1]
            # Skip the herb if the total time exceeds the limit
            if j < herb_time:
                dp[i][j] = dp[i-1][j]
            else:
                # Include the herb if taking it maximizes the value while staying within the time limit
                dp[i][j] = max(dp[i-1][j], dp[i-1][j-herb_time] + herb_value)

    # The maximum value is stored in dp[M][T]
    max_value = dp[M][T]

    return max_value

def max_herb_value(T: int, M: int, herbs: List[Tuple[int, int]]) -> int:
    # Initialize a 2D list for dynamic programming
    dp = [[0] * (T + 1) for _ in range(M + 1)]

    # Iterate through each herb and each possible time
    for i in range(1, M + 1):
        for j in range(1, T + 1):
            # If the herb can be picked within the time limit
            if herbs[i - 1][0] <= j:
                # Update the maximum value at dp[i][j] (max of picking it or not picking it)
                dp[i][j] = max(dp[i - 1][j], dp[i - 1][j - herbs[i - 1][0]] + herbs[i - 1][1])
            # If the herb cannot be picked within the time limit
            else:
                # Copy the maximum value from the previous row
                dp[i][j] = dp[i - 1][j]

    # The result is the maximum value that can be picked within the time limit
    return dp[M][T]

def min_remaining_space(V: int, n: int, volumes: List[int]) -> int:
    # Initialize a dynamic programming table of size (V+1) x (n+1)
    dp = [[0] * (n + 1) for _ in range(V + 1)]

    # Base case: no volumes and no items
    for i in range(1, V + 1):
        dp[i][0] = 0

    for j in range(1, n + 1):
        for i in range(1, V + 1):
            # If the current volume of the box is less than the volume of the current item, ignore it
            if i < volumes[j - 1]:
                dp[i][j] = dp[i][j - 1]
            # If the current volume of the box can accommodate the current item
            else:
                dp[i][j] = max(dp[i][j - 1], dp[i - volumes[j - 1]][j - 1] + volumes[j - 1])

    # The maximum volume that can be occupied in the box is the value in dp[V][n]
    max_occupied_volume = dp[V][n]

    # The minimum remaining space is the difference between the box's total capacity and the maximum occupied volume
    min_remaining_space = V - max_occupied_volume

    return min_remaining_space

def min_remaining_space(V: int, n: int, volumes: List[int]) -> int:
    # Initialize the dp table to store the maximum volume that can be occupied by any subset of the given items
    dp = [0] * (V + 1)
    for v in volumes:
        for i in range(V, v - 1, -1):
            dp[i] = max(dp[i], dp[i - v] + v)

    # Return the difference between the box's total capacity and the maximum occupied volume, which is the minimum remaining space
    remaining_space = V - dp[V]
    return remaining_space

def min_remaining_space(V, n, volumes):
    # Create a table to store the subproblems
    dp = [[0] * (V + 1) for _ in range(n + 1)]

    # Fill the table by considering each item
    for i in range(1, n + 1):
        for j in range(1, V + 1):
            if volumes[i - 1] <= j:
                dp[i][j] = max(dp[i - 1][j], dp[i - 1][j - volumes[i - 1]] + volumes[i - 1])
            else:
                dp[i][j] = dp[i - 1][j]

    # Calculate the minimum remaining space
    min_remaining = V - dp[n][V]

    return min_remaining

def min_remaining_space(V, n, volumes):
    dp = [0] * (V + 1)
    for i in range(1, n + 1):
        for j in range(V, volumes[i - 1] - 1, -1):
            dp[j] = max(dp[j], dp[j - volumes[i - 1]] + volumes[i - 1])
    return V - max(dp)

def min_remaining_space(V: int, n: int, volumes: List[int]) -> int:
    values = [0] + [min(V, v) for v in volumes]
    matrix = [[0]*(n+1) for _ in range(V + 1)]

    for v in range(1, V + 1):
        for i in range(1, n + 1):
            if volumes[i-1] <= v:
                matrix[v][i] = max(values[i] + matrix[v - volumes[i-1]][i-1], matrix[v][i-1])
            else:
                matrix[v][i] = matrix[v][i-1]

    remaining_space = V - matrix[V][n]
    return remaining_space

def calculate_arrangements(n, m, a):
    mod = 10**6 + 7
    dp = [0] * (m + 1)
    dp[0] = 1
    for i in range(1, m + 1):
        for j in range(n):
            if i - a[j] >= 0:
                dp[i] = (dp[i] + dp[i - a[j]]) % mod
    return dp[m]

def calculate_arrangements(n, m, a):
    MOD = 10**6 + 7

    # Sort the maximum number of pots per type in descending order
    a.sort(reverse=True)

    def count_arrangements(i, pots):
        if i == n - 1:
            return 1

        arrangements = 0
        for j in range(1, pots + 1 if j <= a[i] else a[i] + 1):
            arrangements = (arrangements + count_arrangements(i + 1, pots - j)) % MOD
        return arrangements
    return count_arrangements(0, m)

def calculate_arrangements(n, m, a) -> int:
    MOD = 10**6 + 7
    dp = [1] * (m + 1)

    for i in range(1, n + 1):
        new_dp = [0] * (m + 1)
        for j in range(m + 1):
            if j < a[i - 1]:
                new_dp[j] = (new_dp[j] + dp[j]) % MOD
            else:
                new_dp[j] = (new_dp[j] + dp[j - a[i - 1]]) % MOD

        dp = new_dp

    return dp[m]

def calculate_arrangements(n, m, a):
    MOD = 10**6 + 7
    dp = [[0] * (m+1) for _ in range(n+1)]
    dp[0][0] = 1

    for type_ in range(1, n+1):
        max_pots = a[type_-1]
        for pots in range(0, m+1):
            dp[type_][pots] += dp[type_-1][pots - max_pots] if pots >= max_pots else 0

    total_arrangements = sum(dp[n]) % MOD
    return total_arrangements

def calculate_arrangements(n, m, a):
    MOD = 10**6 + 7
    results = [0] * (m + 1)
    results[0] = 1

    for i in range(1, n + 1):
        for j in range(a[i - 1], m + 1):
            results[j] = (results[j] + results[j - a[i - 1]]) % MOD

    return results[m]

def vigenere_decrypt(key: str, ciphertext: str) -> str:
    result = ""
    key_length = len(key)
    for i in range(len(ciphertext)):
        char = ciphertext[i]
        if char.isalpha():
            shift = ord(key[i % key_length].lower()) - ord('a')
            if 'a' <= char <= 'z':
                result += chr((ord(char) - ord('a') - shift + 26) % 26 + ord('a'))
            elif 'A' <= char <= 'Z':
                result += chr((ord(char) - ord('A') - shift + 26) % 26 + ord('A'))
        else:
            result += char
    return result

def mod_inverse(a, b):
    if a == 0:
        return None
    x, y = 0, 1
    last_x, last_y = 1, 0
    while b > 0:
        quotient = a // b
        a, b = b, a % b
        x, last_x = last_x - quotient * x, x
        y, last_y = last_y - quotient * y, y
    if a != 1:
        return None
    return last_x % b

def mod_inverse(a, b):
    if a == 0 or b == 0:
        return None
    x, y, u, v = 1, 0, 0, 1
    while b:
        q, r = divmod(a, b)
        x, u = u - q * x, x
        y, v = v - q * y, y
        a, b = b, r
    return u % b

def mod_inverse(a, b):
    if b == 0:
        return None

    x = 0
    y = 1

    if a > b:
        a, b = b, a

    while b != 0:
        quotient = a // b
        a, b = b, a % b
        x, y = y - quotient * x, x

    if x < 0:
        x += b

    return x

def mod_inverse(a, b):
    if gcd(a, b) != 1:
