def next_permutation(perm): 
    k = len(perm) - 2
    while k >= 0:
        if perm[k] < perm[k + 1]:
            break
        k -= 1
    if k < 0:
        return False 

    j = len(perm) - 1
    while perm[j] < perm[k]:
        j -= 1

    perm[k], perm[j] = perm[j], perm[k] 

    perm[k + 1:] = list(reversed(perm[k + 1:])) 

    return True

def next_permutation(perm: list) -> bool:
    # Find the first decreasing index from the right
    for i in range(len(perm) - 2, -1, -1):
        if perm[i] < perm[i + 1]:
            break
    else:
        # If no decreasing index is found, the permutation is the last one
        return False

    # Find the smallest element bigger than perm[i] from the right
    for j in range(len(perm) - 1, i, -1):
        if perm[j] > perm[i]:
            break

    # Swap perm[i] with perm[j]
    perm[i], perm[j] = perm[j], perm[i]

    # Reverse the elements from i+1 to len(perm)
    perm[i + 1:] = perm[i + 1:][::-1]

    return True

