def minimum_students_to_leave(heights: List[int]) -> int:
    """
    Calculate the minimum number of students that need to leave to form a choir formation.
    A choir formation is defined such that for some position 'i', the heights of students
    increase from the start to 'i' and decrease from 'i' to the end of the formation.

    Args:
    heights (List[int]): A list of student heights.

    Returns:
    int: The minimum number of students that need to leave.
    """
    if not heights or len(heights) == 1:
        return 0

    choices = [0, len(heights) - 1]
    min_students_to_leave = len(heights)

    for i in range(1, len(heights)):
        if heights[i] >= heights(choices[0]] and heights[i] <= heights(choices[1]):
            continue
        for j in range(i):
            if heights[j] >= heights[i]:
                choices[0] = j
                for k in range(i, len(heights)):
                    if heights[k] <= heights[j]:
                        choices[1] = k
                        break
        min_students_to_leave = min(min_students_to_leave, len(heights) - i - 1)

    return min_students_to_leave

def minimum_students_to_leave(heights):
    # Initialize a list to keep track of the start of non-decreasing subarrays
    non_decreasing_starts = []

    # Iterate through the heights
    for i in range(len(heights)):
        # Add the current student's position to non_decreasing_starts if the current position is greater than or equal to the last position in the current non-decreasing subarray
        if not non_decreasing_starts or heights[i] >= heights[non_decreasing_starts[-1]]:
            non_decreasing_starts.append(i)

    # Calculate the minimum number of students to leave
    min_students_to_leave = 0
    for i in range(len(heights)):
        # Check if the current position is less than the last position in the corresponding non-decreasing subarray in the non_decreasing starts list
        if heights[i] < heights[non_decreasing_starts[i - 1] if i > 0 else 0]:
            min_students_to_leave += non_decreasing_starts[i - 1] - i

    # The total number of students in the choir formation is the total number of heights minus the total number of students that need to leave
    return len(heights) - min_students_to_leave

def minimum_students_to_leave(heights):
    i = 0
    j = len(heights) - 1

    result = j

    while i <= j:
        if heights[i] <= heights[j]:
