def min_groups(w, n, prices):
    # Initialize a list to keep track of the group sizes
    group_sizes = []

    # Iterate through each souvenir
    for ii in range(n // 2):
        # Calculate the maximum price for a new group
        max_price = prices[ii] + prices[ii + 1]

        # If adding the current souvenir does not exceed the total limit
        if max_price <= w:
            group_sizes.append(max_price)
        else:
            # If adding the current souvenir exceeds the limit, create a new smaller group
            group_sizes.append(prices[ii])
            group_sizes.append(prices[ii + 1])

    # If there are any leftover souvenirs, create a new group with them
    if n % 2 != 0:
