    return len(group_sizes)

def min_groups(w, n, prices):
    price_sum = sum(prices)
    if n > price_sum // w and w == 1:
        return -1

    def helper(remaining_souvenirs, total_price):
        if remaining_souvenirs == 0:
            return 1
        elif total_price > price_sum or total_price > w:
            return -1
        else:
            max_groups = n - remaining_souvenirs
            min_groups = float('inf')
            for group_size in range(1, max_groups + 1):
                if total_price + group_size * w <= price_sum:
                    min_groups = min(min_groups, 1 + helper(remaining_souvenirs - group_size, total_price + group_size * w))
            return min_groups

    return helper(n, 0)

def hanoi_double_iterative(n: int) -> int:
    if n <= 0:
        return 0

    # Recursive relation for the double-disc Hanoi Towers problem
    def hanoi(n):
        return 1 + 2 * hanoi(n - 1)

    # Total number of moves for a pair of discs is 1 (initial move from A to B) plus the number of moves required for n - 1 pairs
    moves = hanoi(n) + (2 * (2**(2**n) - 2 - 1))

    return moves

def hanoi_double_iterative(n: int) -> int:
    # The formula to calculate the minimum number of moves for n pairs of discs in the double-disc Hanoi Towers is 2^n + 1
    return (2 ** n) + 1

